<?php

use App\Http\Controllers\Api\V1\OfficeErp\OfficeErpClientController;
use App\Http\Controllers\Api\V1\OfficeErp\OfficeErpContextController;
use App\Http\Controllers\Api\V1\OfficeErp\OfficeErpContractController;
use App\Http\Controllers\Api\V1\OfficeErp\OfficeErpInvitationController;
use App\Http\Controllers\Api\V1\OfficeErp\OfficeErpInvoiceController;
use App\Http\Controllers\Api\V1\OfficeErp\OfficeErpOperationController;
use App\Http\Controllers\Api\V1\OfficeErp\OfficeErpReceiptController;
use App\Http\Controllers\Api\V1\OfficeErp\OfficeErpReceiptProofController;
use App\Http\Controllers\Api\V1\OfficeErp\OfficeErpSalesPlanController;
use App\Http\Controllers\Api\V1\OfficeErp\OfficeErpSettingsController;
use App\Http\Controllers\Api\V1\OfficeErp\OfficeErpSummaryController;
use App\Http\Middleware\ResolveOfficeErpCommercial;
use Illuminate\Support\Facades\Route;

Route::prefix('erp-commercial')->middleware(ResolveOfficeErpCommercial::class)->group(function (): void {
    Route::get('/context', OfficeErpContextController::class)->name('office-erp-commercial.context');
    Route::get('/summary', OfficeErpSummaryController::class)->name('office-erp-commercial.summary');
    Route::get('/operations/{key}', OfficeErpOperationController::class)->name('office-erp-commercial.operations.lookup');
    Route::get('/receipts', [OfficeErpReceiptController::class, 'index'])->name('office-erp-commercial.receipts.index');
    Route::post('/receipts', [OfficeErpReceiptController::class, 'store'])->name('office-erp-commercial.receipts.store');
    Route::get('/receipts/{receipt}', [OfficeErpReceiptController::class, 'show'])->whereNumber('receipt')->name('office-erp-commercial.receipts.show');
    Route::post('/receipts/{receipt}/reverse', [OfficeErpReceiptController::class, 'reverse'])->whereNumber('receipt')->name('office-erp-commercial.receipts.reverse');
    Route::post('/receipt-proofs', [OfficeErpReceiptProofController::class, 'store'])->name('office-erp-commercial.receipt-proofs.store');
    Route::get('/receipt-proofs/{proofId}', [OfficeErpReceiptProofController::class, 'download'])->whereUuid('proofId')->name('office-erp-commercial.receipt-proofs.download');
    Route::get('/clients', [OfficeErpClientController::class, 'index'])->name('office-erp-commercial.clients.index');
    Route::get('/contracts', [OfficeErpContractController::class, 'index'])->name('office-erp-commercial.contracts.index');
    Route::get('/contracts/{contract}', [OfficeErpContractController::class, 'show'])->whereNumber('contract')->name('office-erp-commercial.contracts.show');
    Route::post('/contracts/{contract}/activate', [OfficeErpContractController::class, 'activate'])->whereNumber('contract')->name('office-erp-commercial.contracts.activate');
    Route::patch('/contracts/{contract}/terms', [OfficeErpContractController::class, 'amend'])->whereNumber('contract')->name('office-erp-commercial.contracts.amend');
    Route::post('/contracts/{contract}/renew', [OfficeErpContractController::class, 'renew'])->whereNumber('contract')->name('office-erp-commercial.contracts.renew');
    Route::post('/contracts/{contract}/suspend', [OfficeErpContractController::class, 'suspend'])->whereNumber('contract')->name('office-erp-commercial.contracts.suspend');
    Route::post('/contracts/{contract}/resume', [OfficeErpContractController::class, 'resume'])->whereNumber('contract')->name('office-erp-commercial.contracts.resume');
    Route::post('/contracts/{contract}/cancel', [OfficeErpContractController::class, 'cancel'])->whereNumber('contract')->name('office-erp-commercial.contracts.cancel');
    Route::post('/clients/{client}/onboarding-preview', [OfficeErpClientController::class, 'preview'])->whereNumber('client')->name('office-erp-commercial.clients.preview');
    Route::post('/clients/{client}/invitations', [OfficeErpInvitationController::class, 'store'])->whereNumber('client')->name('office-erp-commercial.invitations.store');
    Route::post('/invitations/{invitation}/revoke', [OfficeErpInvitationController::class, 'revoke'])->whereNumber('invitation')->name('office-erp-commercial.invitations.revoke');
    Route::post('/invitations/{invitation}/reissue', [OfficeErpInvitationController::class, 'reissue'])->whereNumber('invitation')->name('office-erp-commercial.invitations.reissue');
    Route::get('/invoices', [OfficeErpInvoiceController::class, 'index'])->name('office-erp-commercial.invoices.index');
    Route::post('/invoices', [OfficeErpInvoiceController::class, 'store'])->name('office-erp-commercial.invoices.store');
    Route::get('/invoices/{invoice}', [OfficeErpInvoiceController::class, 'show'])->whereNumber('invoice')->name('office-erp-commercial.invoices.show');
    Route::patch('/invoices/{invoice}', [OfficeErpInvoiceController::class, 'update'])->whereNumber('invoice')->name('office-erp-commercial.invoices.update');
    Route::post('/invoices/{invoice}/issue', [OfficeErpInvoiceController::class, 'issue'])->whereNumber('invoice')->name('office-erp-commercial.invoices.issue');
    Route::post('/invoices/{invoice}/adjustments', [OfficeErpInvoiceController::class, 'adjust'])->whereNumber('invoice')->name('office-erp-commercial.invoices.adjust');
    Route::post('/invoices/{invoice}/cancel', [OfficeErpInvoiceController::class, 'cancel'])->whereNumber('invoice')->name('office-erp-commercial.invoices.cancel');
    Route::get('/settings', [OfficeErpSettingsController::class, 'show'])->name('office-erp-commercial.settings.show');
    Route::patch('/settings', [OfficeErpSettingsController::class, 'update'])->name('office-erp-commercial.settings.update');
    Route::post('/settings/preview', [OfficeErpSettingsController::class, 'preview'])->name('office-erp-commercial.settings.preview');
    Route::get('/plans', [OfficeErpSalesPlanController::class, 'index'])->name('office-erp-commercial.plans.index');
    Route::post('/plans', [OfficeErpSalesPlanController::class, 'store'])->name('office-erp-commercial.plans.store');
    Route::get('/plans/{plan}', [OfficeErpSalesPlanController::class, 'show'])->whereNumber('plan')->name('office-erp-commercial.plans.show');
    Route::post('/plans/{plan}/revisions', [OfficeErpSalesPlanController::class, 'revise'])->whereNumber('plan')->name('office-erp-commercial.plans.revise');
    Route::post('/plans/{plan}/archive', [OfficeErpSalesPlanController::class, 'archive'])->whereNumber('plan')->name('office-erp-commercial.plans.archive');
});
